const sd = $getWorkflowStaticData('global');
const last = parseInt(sd.lastUpdateId, 10) || 0;
// offset 0 on a cold start means "give me whatever is still queued"
return [{ json: { offset: last > 0 ? last + 1 : 0, lastSeen: last } }];

const cfg = $('P. Config').first().json;

// ---- shared helpers -------------------------------------------------
const TZ = cfg.TZ || 'Asia/Dhaka';
const dfmt = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
const sfmt = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
const today = dfmt.format(new Date());
const nowStamp = sfmt.format(new Date());

const addDays = (iso, n) => {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + (parseInt(n, 10) || 0));
  return d.toISOString().slice(0, 10);
};
const daysBetween = (a, b) =>
  Math.round((new Date(b + 'T00:00:00Z') - new Date(a + 'T00:00:00Z')) / 86400000);
const norm = (v) => {
  if (v === null || v === undefined || v === '') return '';
  const s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const d = new Date(s);
  return isNaN(d.getTime()) ? '' : dfmt.format(d);
};
const esc = (s) => String(s === undefined || s === null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const colLetter = (i) => String.fromCharCode(65 + i);

// Tasks sheet layout: A..U. Bot owns A and I..U.
const TASK_COLS = ['Task ID','Task Name','Assignee','Telegram User ID','Duration','Interval',
  'Repeat','Repeat Every','Start Date','End Date','Next Run','Status','Cycle','Last Sent',
  'Completed At','Completed By','Method','Proof URL','Extension Days','Extension Count','DM Message ID'];
// index inside the I..U slice (13 wide)
const IJ = { start:0, end:1, next:2, status:3, cycle:4, lastSent:5, completedAt:6,
             completedBy:7, method:8, proof:9, extDays:10, extCount:11, dmMsgId:12 };

function parseTasks(values) {
  if (!values || values.length < 2) return [];
  const head = (values[0] || []).map((h) => String(h || '').trim());
  const at = (name) => head.indexOf(name);
  for (const c of TASK_COLS) {
    if (at(c) < 0) throw new Error('Tasks sheet is missing the column: ' + c);
  }
  const out = [];
  for (let r = 1; r < values.length; r++) {
    const row = values[r] || [];
    const g = (name) => String(row[at(name)] === undefined ? '' : row[at(name)]).trim();
    const taskName = g('Task Name');
    const userId = g('Telegram User ID');
    if (!taskName && !userId) continue;             // truly blank row
    const raw = [];
    for (let i = 8; i <= 20; i++) raw.push(row[i] === undefined ? '' : row[i]);
    out.push({
      rowNumber: r + 1,
      id: g('Task ID'),
      name: taskName,
      assignee: g('Assignee') || 'Unassigned',
      userId,
      duration: parseInt(g('Duration'), 10) || 0,
      interval: parseInt(g('Interval'), 10) || 0,
      repeat: g('Repeat').toLowerCase() === 'yes',
      repeatEvery: parseInt(g('Repeat Every'), 10) || 0,
      start: norm(g('Start Date')),
      end: norm(g('End Date')),
      next: norm(g('Next Run')),
      status: g('Status'),
      cycle: parseInt(g('Cycle'), 10) || 1,
      extDays: parseInt(g('Extension Days'), 10) || 0,
      extCount: parseInt(g('Extension Count'), 10) || 0,
      dmMsgId: g('DM Message ID'),
      raw,
    });
  }
  return out;
}

// ---------------------------------------------------------------- main
const ADMIN_IDS = String(cfg.ADMIN_IDS || '').split(',').map((s) => s.trim()).filter(Boolean);
const MAX_EXT = parseInt(cfg.MAX_EXTENSIONS, 10) || 2;
const GROUP = String(cfg.GROUP_CHAT_ID);



// ---------------------------------------------------------------- polling
const sd = $getWorkflowStaticData('global');
const updates = ($('P. Get updates').first().json.result) || [];
const tasks = parseTasks($('P. Read Tasks').first().json.values);
const peopleVals = $input.first().json.values || [];

const ops = [];
let maxId = parseInt(sd.lastUpdateId, 10) || 0;

function routeUpdate(u) {
  const fullName = (f) => [f.first_name, f.last_name].filter(Boolean).join(' ').trim() || String(f.id);

  if (u.callback_query) {
    const q = u.callback_query;
    const p = String(q.data || '').split(':');
    return { type: 'callback', action: p[0] || '', taskId: p[1] || '', arg: p[2] || '',
      callbackQueryId: q.id, actorId: q.from.id, actorName: fullName(q.from),
      chatId: (q.message && q.message.chat) ? q.message.chat.id : q.from.id,
      messageId: q.message ? q.message.message_id : null,
      originalText: (q.message && q.message.text) ? q.message.text : '' };
  }

  if (u.message && (u.message.photo || u.message.document)) {
    const m = u.message;
    return { type: 'proof',
      fileId: m.photo ? m.photo[m.photo.length - 1].file_id : m.document.file_id,
      actorId: m.from.id, actorName: fullName(m.from), chatId: m.chat.id,
      messageId: m.message_id,
      replyToId: m.reply_to_message ? m.reply_to_message.message_id : null,
      caption: String(m.caption || '').trim(), taskId: '' };
  }

  if (u.message && typeof u.message.text === 'string') {
    // "/task@ailnotbot a | b" -> cmd "task", args "a | b"
    const hit = u.message.text.trim().match(/^\/([A-Za-z_]+)(?:@[A-Za-z0-9_]+)?(?:\s+([\s\S]*))?$/);
    if (hit) {
      const f = u.message.from;
      const cmd = hit[1].toLowerCase();
      const base = { actorId: f.id, actorName: fullName(f), chatId: u.message.chat.id,
        messageId: u.message.message_id, taskId: '' };
      if (cmd === 'start') {
        return Object.assign(base, { type: 'register',
          username: f.username ? '@' + f.username : '' });
      }
      return Object.assign(base, { type: 'command', cmd, args: (hit[2] || '').trim(),
        replyToUserId: (u.message.reply_to_message && u.message.reply_to_message.from)
          ? u.message.reply_to_message.from.id : null });
    }
  }

  return null;
}

function handle(ctx) {
const tg = (method, body) => ops.push({ json: { op: 'telegram', method, body } });
const sheetsBatch = (data) => ops.push({ json: { op: 'sheetsBatch', body: { valueInputOption: 'RAW', data } } });
const append = (tab, row) => ops.push({ json: { op: 'sheetsAppend', tab, body: { values: [row] } } });
const logIt = (event, detail) => append('Log', [nowStamp, ctx.taskId || '', event, ctx.actorName || '', detail || '']);
const answer = (text, alert) => {
  if (ctx.callbackQueryId) {
    tg('answerCallbackQuery', { callback_query_id: ctx.callbackQueryId, text: String(text).slice(0, 190), show_alert: !!alert });
  }
};
const reply = (text) => tg('sendMessage', { chat_id: ctx.chatId, parse_mode: 'HTML', text });
const toGroup = (text) => tg('sendMessage', { chat_id: GROUP, parse_mode: 'HTML', disable_web_page_preview: true, text });

function writeTask(t, patch) {
  const v = (Array.isArray(t.raw) ? t.raw.slice(0, 13) : []).map((x) => (x === undefined ? '' : x));
  while (v.length < 13) v.push('');
  for (const k of Object.keys(patch)) v[IJ[k]] = patch[k];
  sheetsBatch([{ range: 'Tasks!I' + t.rowNumber + ':U' + t.rowNumber, values: [v] }]);
}

const PEOPLE = (() => {
  const out = [];
  for (let r = 1; r < peopleVals.length; r++) {
    const row = peopleVals[r] || [];
    const id = String(row[2] === undefined ? '' : row[2]).trim();
    if (!id) continue;
    out.push({
      rowNumber: r + 1,
      name: String(row[0] || '').trim() || id,
      username: String(row[1] || '').trim(),
      id,
      role: String(row[3] || '').trim().toLowerCase(),
    });
  }
  return out;
})();
const personName = (id) => { const p = PEOPLE.find((x) => x.id === String(id)); return p ? p.name : String(id); };
const isAdmin = (id) => ADMIN_IDS.includes(String(id)) || PEOPLE.some((p) => p.id === String(id) && p.role === 'admin');

const taskButtons = (id) => ({ inline_keyboard: [
  [{ text: '\u2705 Mark as Done', callback_data: 'done:' + id },
   { text: '\u23F0 Snooze 2 days', callback_data: 'snooze:' + id }],
  [{ text: '\uD83D\uDD01 Not mine', callback_data: 'reassign:' + id },
   { text: '\u23F3 Request extension', callback_data: 'extreq:' + id }],
]});

function complete(t, method, proof) {
  append('History', [nowStamp, t.id, t.name, t.assignee, t.cycle, t.start, t.end, method, proof || '']);
  let nextLine = '';
  if (t.repeat) {
    const gap = t.repeatEvery || t.duration;
    const ns = addDays(today, gap);
    const ne = addDays(ns, t.duration);
    writeTask(t, { start: ns, end: ne, next: ns, status: 'Scheduled', cycle: t.cycle + 1,
      lastSent: '', completedAt: '', completedBy: '', method: '', proof: '',
      extDays: 0, extCount: 0, dmMsgId: '' });
    nextLine = '\nNext cycle starts ' + ns + '.';
  } else {
    writeTask(t, { status: 'Completed', completedAt: nowStamp, completedBy: ctx.actorName,
      method, proof: proof || '' });
  }
  if (t.dmMsgId) {
    tg('editMessageText', { chat_id: t.userId, message_id: parseInt(t.dmMsgId, 10), parse_mode: 'HTML',
      text: '<b>' + esc(t.name) + '</b>\n\n\u2705 Completed ' + nowStamp + ' by ' + esc(ctx.actorName) + ' (' + method + ')' });
  }
  toGroup('\u2705 <b>' + esc(t.name) + '</b> completed by ' + esc(ctx.actorName)
    + ' on ' + nowStamp + ' (' + method + ')' + nextLine);
  logIt('completed:' + method, t.name);
}


// ================================================================ COMMANDS
if (ctx.type === 'command') {
  const admin = isAdmin(ctx.actorId);

  if (ctx.cmd === 'help') {
    reply('<b>Commands</b>\n\n'
      + '<code>/task Name | @user | duration | interval</code>\n'
      + '   create and assign a task (admin only)\n'
      + '   add a 5th number to make it repeat, e.g. <code>| 180</code>\n\n'
      + '<code>/tasks</code>  list every open task\n'
      + '<code>/mine</code>   list only your tasks\n'
      + '<code>/start</code>  register yourself and get your ID');
    return;
  }

  if (ctx.cmd === 'tasks' || ctx.cmd === 'mine') {
    let open = tasks.filter((t) => t.status === 'Active' || t.status === 'Expired');
    if (ctx.cmd === 'mine') open = open.filter((t) => t.userId === String(ctx.actorId));
    if (!open.length) { reply(ctx.cmd === 'mine' ? 'You have no open tasks.' : 'No open tasks.'); return; }
    open.sort((a, b) => String(a.end || '').localeCompare(String(b.end || '')));
    reply('<b>' + (ctx.cmd === 'mine' ? 'Your open tasks' : 'Open tasks') + '</b>\n'
      + open.map((t) => {
          const left = t.end ? daysBetween(today, t.end) : null;
          const flag = left === null ? '\u2022' : left < 0 ? '\uD83D\uDD34' : left <= 7 ? '\u26A0\uFE0F' : '\u2022';
          const tail = left === null ? '' : left < 0 ? ' \u2014 OVERDUE' : ' \u2014 ' + left + 'd left';
          return flag + ' <b>' + esc(t.name) + '</b> \u2014 ' + esc(t.assignee) + tail + ' (' + t.id + ')';
        }).join('\n'));
    return;
  }

  if (ctx.cmd === 'task') {
    if (!admin) { reply('Only an admin can create tasks.'); return; }

    const usage = 'Format:\n<code>/task Task Name | @username | duration | interval</code>\n\n'
      + 'Example:\n<code>/task Safety Shoes | @manum_arl | 60 | 7</code>\n\n'
      + 'Add a 5th number to repeat it after completion:\n'
      + '<code>/task Safety Shoes | @manum_arl | 60 | 7 | 180</code>';

    const parts = String(ctx.args || '').split('|').map((x) => x.trim());
    if (parts.length < 4) { reply(usage); return; }

    const taskName = parts[0];
    const whoRaw = parts[1];
    const duration = parseInt(parts[2], 10);
    const interval = parseInt(parts[3], 10);
    const repeatEvery = parseInt(parts[4], 10) || 0;

    if (!taskName) { reply('The task name is missing.\n\n' + usage); return; }
    if (!duration || !interval) { reply('Duration and interval must be numbers.\n\n' + usage); return; }
    if (interval > duration) { reply('Interval (' + interval + ') is longer than duration (' + duration + ') \u2014 only the day-0 notice would ever fire.'); return; }

    // resolve the assignee: reply-to > numeric id > @username > display name
    const who = String(whoRaw || '').replace(/^@/, '').toLowerCase();
    let person = null;
    if (ctx.replyToUserId) person = PEOPLE.find((p) => p.id === String(ctx.replyToUserId));
    if (!person && /^[0-9]+$/.test(who)) person = PEOPLE.find((p) => p.id === who);
    if (!person) person = PEOPLE.find((p) => p.username.replace(/^@/, '').toLowerCase() === who);
    if (!person) person = PEOPLE.find((p) => p.name.toLowerCase() === who);
    if (!person) {
      reply('I don\'t know <b>' + esc(whoRaw) + '</b> \u2014 they must send me /start first.\n\n'
        + '<b>Registered:</b>\n'
        + (PEOPLE.length ? PEOPLE.map((p) => '\u2022 ' + esc(p.name) + (p.username ? ' ' + esc(p.username) : '')).join('\n') : '(nobody yet)'));
      return;
    }

    const taskId = 'T-' + Math.random().toString(36).slice(2, 8).toUpperCase();
    const end = addDays(today, duration);
    const nextRun = addDays(today, interval);   // day 0 is announced right now

    append('Tasks', [taskId, taskName, person.name, person.id, duration, interval,
      repeatEvery ? 'Yes' : '', repeatEvery || '',
      today, end, nextRun, 'Active', 1, today, '', '', '', '', 0, 0, '']);

    toGroup('\uD83C\uDD95 <b>Task Assigned</b>\n\nTask: <b>' + esc(taskName) + '</b>\n'
      + 'Assigned to: <a href="tg://user?id=' + person.id + '">' + esc(person.name) + '</a>\n'
      + 'Deadline: ' + end + ' (' + duration + ' days)\n'
      + 'Reminders every ' + interval + ' day(s)'
      + (repeatEvery ? '\nRepeats ' + repeatEvery + ' days after completion' : '')
      + '\nCreated by ' + esc(ctx.actorName) + ' \u00B7 Ref: ' + taskId);

    tg('sendMessage', { chat_id: person.id, parse_mode: 'HTML',
      text: '\uD83C\uDD95 ' + esc(ctx.actorName) + ' assigned you a task.\n\n'
        + '<b>' + esc(taskName) + '</b>\nDeadline: ' + end + ' \u2014 ' + duration + ' day(s) left\n\n'
        + 'Press \u2705 when done, or reply to this message with a photo as proof.',
      reply_markup: taskButtons(taskId) });

    ctx.taskId = taskId;
    logIt('created', taskName + ' -> ' + person.name);
    return;
  }

  reply('Unknown command \u2014 try /help');
  return;
}

// ================================================================ REGISTER
if (ctx.type === 'register') {
  const existing = PEOPLE.find((p) => p.id === String(ctx.actorId));
  if (existing) {
    sheetsBatch([{ range: 'People!A' + existing.rowNumber + ':C' + existing.rowNumber,
      values: [[ctx.actorName, ctx.username, String(ctx.actorId)]] }]);
  } else {
    append('People', [ctx.actorName, ctx.username, String(ctx.actorId), '']);
  }
  reply('\u2705 Registered.\n\nYour Telegram User ID is <code>' + ctx.actorId + '</code>\n'
    + 'Give this to the admin so they can assign you tasks.');
  return;
}

// ================================================================ PHOTO PROOF
if (ctx.type === 'proof') {
  const open = tasks.filter((t) => t.userId === String(ctx.actorId)
    && (t.status === 'Active' || t.status === 'Expired'));
  if (open.length === 0) { reply('You have no open tasks right now.'); return; }

  let m = null;
  // 1. replied directly to the reminder DM \u2014 most reliable
  if (ctx.replyToId) m = open.find((t) => t.dmMsgId && String(t.dmMsgId) === String(ctx.replyToId));
  // 2. task ref written in the caption
  if (!m && ctx.caption) {
    const cap = ctx.caption.toUpperCase();
    m = open.find((t) => t.id && cap.indexOf(t.id.toUpperCase()) >= 0);
  }
  // 3. only one open task \u2014 unambiguous
  if (!m && open.length === 1) m = open[0];

  if (!m) {
    reply('You have ' + open.length + ' open tasks. Reply directly to the reminder message for the '
      + 'one you finished, or put its ref in the caption:\n'
      + open.map((t) => '\u2022 ' + esc(t.name) + ' (' + t.id + ')').join('\n'));
    return;
  }

  ctx.taskId = m.id;
  // put the photo in the group so the proof is visible to everyone
  tg('copyMessage', { chat_id: GROUP, from_chat_id: ctx.chatId, message_id: ctx.messageId,
    caption: '\uD83D\uDCF7 Proof: <b>' + esc(m.name) + '</b> \u2014 ' + esc(ctx.actorName), parse_mode: 'HTML' });
  complete(m, 'Photo', ctx.fileId);
  reply('\u2705 Proof received \u2014 <b>' + esc(m.name) + '</b> marked complete.');
  return;
}

// ================================================================ BUTTONS
if (ctx.type !== 'callback') return;

if (ctx.action === 'cancel') {
  tg('deleteMessage', { chat_id: ctx.chatId, message_id: ctx.messageId });
  answer('Cancelled');
  return;
}

const t = tasks.find((x) => x.id && x.id === ctx.taskId);
if (!t) { answer('Task not found \u2014 it may have been deleted.', true); return; }

const admin = isAdmin(ctx.actorId);
const mine = String(ctx.actorId) === t.userId;
const adminOnly = (ctx.action === 'extok' || ctx.action === 'extno');

if (adminOnly && !admin) { answer('Only an admin can approve extensions.', true); return; }
if (!adminOnly && !mine && !admin) { answer('This task is assigned to someone else.', true); return; }
if (t.status === 'Completed' && ctx.action !== 'extok') { answer('This task is already closed.', true); return; }

// ---- done ----
if (ctx.action === 'done') { complete(t, 'Button', ''); answer('\u2705 Marked complete'); return; }

// ---- snooze ----
if (ctx.action === 'snooze') {
  const to = addDays(today, 2);
  writeTask(t, { next: to });
  answer('\u23F0 Snoozed until ' + to);
  logIt('snoozed', 'until ' + to);
  return;
}

// ---- reassign: show the people picker ----
if (ctx.action === 'reassign') {
  const cands = PEOPLE.filter((p) => p.id !== t.userId);
  if (cands.length === 0) { answer('Nobody else is registered \u2014 they must /start the bot first.', true); return; }
  const btns = cands.map((p) => ({ text: p.name, callback_data: 'assign:' + t.id + ':' + p.id }));
  const kb = [];
  for (let i = 0; i < btns.length; i += 2) kb.push(btns.slice(i, i + 2));
  kb.push([{ text: '\u2716\uFE0F Cancel', callback_data: 'cancel:' + t.id }]);
  tg('sendMessage', { chat_id: ctx.chatId, parse_mode: 'HTML',
    text: 'Who should <b>' + esc(t.name) + '</b> go to?\nThe deadline stays ' + t.end + '.',
    reply_markup: { inline_keyboard: kb } });
  answer('Pick the new assignee');
  return;
}

// ---- assign: apply the reassignment ----
if (ctx.action === 'assign') {
  const newId = String(ctx.arg || '').trim();
  if (!newId) { answer('No person selected.', true); return; }
  const newName = personName(newId);
  const oldName = t.assignee;
  sheetsBatch([{ range: 'Tasks!C' + t.rowNumber + ':D' + t.rowNumber, values: [[newName, newId]] }]);
  writeTask(t, { next: today, dmMsgId: '' });   // fresh DM on the next scheduler run
  tg('editMessageText', { chat_id: ctx.chatId, message_id: ctx.messageId, parse_mode: 'HTML',
    text: '\uD83D\uDD01 Reassigned <b>' + esc(t.name) + '</b> to ' + esc(newName) + '.' });
  tg('sendMessage', { chat_id: newId, parse_mode: 'HTML',
    text: '\uD83D\uDD01 <b>' + esc(t.name) + '</b> has been reassigned to you by ' + esc(ctx.actorName)
      + '.\nDeadline: ' + t.end + ' (unchanged)',
    reply_markup: taskButtons(t.id) });
  toGroup('\uD83D\uDD01 <b>' + esc(t.name) + '</b> reassigned from ' + esc(oldName) + ' to '
    + '<a href="tg://user?id=' + newId + '">' + esc(newName) + '</a> by ' + esc(ctx.actorName)
    + '. Deadline unchanged: ' + t.end + '.');
  answer('\u2705 Reassigned to ' + newName);
  logIt('reassigned', oldName + ' -> ' + newName);
  return;
}

// ---- extension: ask how many days ----
if (ctx.action === 'extreq') {
  if (t.extCount >= MAX_EXT) { answer('Extension limit reached (' + MAX_EXT + ').', true); return; }
  tg('sendMessage', { chat_id: ctx.chatId, parse_mode: 'HTML',
    text: '\u23F3 How much more time do you need for <b>' + esc(t.name) + '</b>?',
    reply_markup: { inline_keyboard: [
      [{ text: '+7 days', callback_data: 'extend:' + t.id + ':7' },
       { text: '+14 days', callback_data: 'extend:' + t.id + ':14' },
       { text: '+30 days', callback_data: 'extend:' + t.id + ':30' }],
      [{ text: '\u2716\uFE0F Cancel', callback_data: 'cancel:' + t.id }],
    ]}});
  answer('Pick how many days');
  return;
}

// ---- extension: route to admin for approval ----
if (ctx.action === 'extend') {
  const days = parseInt(ctx.arg, 10) || 0;
  if (!days) { answer('Invalid request.', true); return; }
  if (ADMIN_IDS.length === 0) { answer('No admin configured \u2014 set ADMIN_IDS in the Config node.', true); return; }
  for (const a of ADMIN_IDS) {
    tg('sendMessage', { chat_id: a, parse_mode: 'HTML',
      text: '\u23F3 <b>Extension request</b>\n\n' + esc(ctx.actorName) + ' needs <b>' + days
        + ' more days</b> for <b>' + esc(t.name) + '</b>.\nCurrent deadline: ' + t.end
        + '\nExtensions used: ' + t.extCount + '/' + MAX_EXT,
      reply_markup: { inline_keyboard: [[
        { text: '\u2705 Approve +' + days + 'd', callback_data: 'extok:' + t.id + ':' + days },
        { text: '\u274C Deny', callback_data: 'extno:' + t.id },
      ]]}});
  }
  tg('editMessageText', { chat_id: ctx.chatId, message_id: ctx.messageId, parse_mode: 'HTML',
    text: '\u23F3 Extension request for <b>' + esc(t.name) + '</b> (+' + days + ' days) sent to the admin.' });
  answer('Sent to admin for approval');
  logIt('extension_requested', '+' + days + ' days');
  return;
}

// ---- extension approved ----
if (ctx.action === 'extok') {
  const days = parseInt(ctx.arg, 10) || 0;
  const base = (t.end && t.end > today) ? t.end : today;   // never extend from a date already past
  const newEnd = addDays(base, days);
  writeTask(t, { end: newEnd, status: 'Active', next: today,
    extDays: t.extDays + days, extCount: t.extCount + 1 });
  tg('sendMessage', { chat_id: t.userId, parse_mode: 'HTML',
    text: '\u2705 Extension approved for <b>' + esc(t.name) + '</b>.\nNew deadline: ' + newEnd });
  tg('editMessageText', { chat_id: ctx.chatId, message_id: ctx.messageId, parse_mode: 'HTML',
    text: '\u2705 Approved +' + days + ' days for <b>' + esc(t.name) + '</b>. New deadline: ' + newEnd });
  toGroup('\u23F3 <b>' + esc(t.name) + '</b> extended by ' + days + ' days. New deadline: ' + newEnd
    + ' (approved by ' + esc(ctx.actorName) + ')');
  answer('Approved');
  logIt('extension_approved', '+' + days + ' days, new deadline ' + newEnd);
  return;
}

// ---- extension denied ----
if (ctx.action === 'extno') {
  tg('sendMessage', { chat_id: t.userId, parse_mode: 'HTML',
    text: '\u274C Extension denied for <b>' + esc(t.name) + '</b>. The deadline stays ' + t.end + '.' });
  tg('editMessageText', { chat_id: ctx.chatId, message_id: ctx.messageId, parse_mode: 'HTML',
    text: '\u274C Denied extension for <b>' + esc(t.name) + '</b>.' });
  answer('Denied');
  logIt('extension_denied', '');
  return;
}

answer('Unknown action.', true);
return;

}

// ---- run every polled update through the same logic ----
for (const u of updates) {
  if (typeof u.update_id === 'number' && u.update_id > maxId) maxId = u.update_id;
  const ctx = routeUpdate(u);
  if (!ctx) continue;
  try { handle(ctx); }
  catch (e) { ops.push({ json: { op: 'telegram', method: 'sendMessage', body: {
    chat_id: cfg.ADMIN_IDS.split(',')[0].trim(), text: 'Handler error: ' + e.message } } }); }
}

if (updates.length > 0) {
  sd.lastUpdateId = maxId;
  // Confirm the batch server-side so Telegram never resends it, even if n8n's
  // static data is lost. This is what makes the poll idempotent.
  ops.push({ json: { op: 'telegram', method: 'getUpdates',
    body: { offset: maxId + 1, limit: 1, timeout: 0 } } });
}

return ops;
